"""Layer 15 MLP down-projection, component 5826: a "complement is coming" detector.

Mostly negative. It is most negative on the function words that open a complement
after a subject or verb: copulas (is, was, are, be), have-verbs (has, had), modals
(will, can, must), and prepositions (by, from, in, with, into, onto). A copula after a
noun subject ("the population [was]") is more negative than one after a pronoun
("it [is]", "there [is]"), and a preposition after a verb ("opened [in]") is more
negative than one after "and" or punctuation.

Other words: verbs sit around -1, adjectives slightly positive (+0.4), nouns near 0.
Punctuation and digits sit near 0.

Exceptions on "of" and "to":
- "of" after a quantifier ("all of", "most of", "each of") is strongly positive.
- "of" after a composition or membership word ("made of", "consists of", "member of")
  is negative.
- "to" after a try-verb ("tried to", "wanted to") is near 0, and after a motion or
  transfer verb ("moved to", "returned to") it is more negative.

Predicted values are typical activations, not exact ones.
"""

import wordnet

READS = ()

COPULAS = {"is", "was", "are", "were", "be", "been", "being", "am"}
HAVE = {"has", "have", "had", "having"}
MODALS = {"will", "would", "could", "should", "might", "may", "can", "must", "shall"}
PREPOSITIONS = {"in", "on", "at", "with", "from", "for", "by", "as", "through", "under",
                "over", "between", "about", "during", "after", "without", "than", "like",
                "via", "within", "across", "toward", "towards", "near", "among", "upon"}
HEAVY_PREPOSITIONS = {"into", "onto"}
EQUALS = {"=", "==", "->"}
PRONOUNS = {"it", "there", "what", "which", "who", "that", "this", "these", "those",
            "he", "she", "they", "we", "i", "you", "here"}
CONJUNCTIONS = {"and", "but", "or", "so"}
QUANTIFIERS = {"all", "each", "both", "most", "many", "some", "any", "none", "rest",
               "majority", "much", "several", "few", "half", "more", "one", "two", "three"}
COMPOSITION = {"made", "composed", "consist", "consists", "consisting", "full", "member",
               "son", "daughter", "capable", "population", "up", "out"}
TRY_VERBS = {"try", "tried", "tries", "trying", "wanted", "prefer", "seem", "hard",
             "attempted", "refused", "how", "impossible", "difficult", "able", "need",
             "decided", "going"}
MOTION_VERBS = {"moved", "returned", "return", "move", "transferred", "belongs", "home",
                "closer", "set", "returning", "back", "went", "sent", "converted",
                "changed", "married", "reduced", "elected", "limited", "added", "connected"}


def is_verb(word):
    return word.isalpha() and wordnet.parts_of_speech(word) == {"verb"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()

    if word in COPULAS:
        if previous in PRONOUNS:
            return carry, -1.5
        if previous.isalpha() and "noun" in wordnet.parts_of_speech(previous):
            return carry, -4.0
        return carry, -3.0
    if word in HAVE:
        return carry, -2.3
    if word in MODALS or word in EQUALS:
        return carry, -1.3
    if word in HEAVY_PREPOSITIONS:
        return carry, -3.2
    if word in PREPOSITIONS:
        if is_verb(previous):
            return carry, -3.0
        if previous in CONJUNCTIONS or not previous.isalpha():
            return carry, -0.5
        return carry, -1.7
    if word == "of":
        if previous in QUANTIFIERS:
            return carry, 2.1
        if previous in COMPOSITION:
            return carry, -1.6
        return carry, 0.5
    if word == "to":
        if previous in TRY_VERBS:
            return carry, 0.0
        if previous in MOTION_VERBS:
            return carry, -1.9
        return carry, -1.5
    if word.isalpha():
        pos = wordnet.parts_of_speech(word)
        if "verb" in pos and "noun" not in pos:
            return carry, -1.0
        if pos == {"adjective"}:
            return carry, 0.4
    return carry, 0.0

"""Predicts layers.15.mlp.down_proj:5830, a near-silent component.

Its activation is a dense linear readout of the layer-15 MLP hidden state, spread over
thousands of hidden units, so no single token or context concept explains it. Two weak
regularities are worth writing down:

1. Position in the document. The first token of a document sits at about zero, the
   second dips to about -0.13, and later tokens sit near the overall mean of -0.03.
2. Kind of token. Relative to that level, whitespace-only and mixed tokens sit a little
   higher, Han characters a little lower, and words, digits and punctuation near it.

The program predicts those levels, counting positions within each document (restarting
where the document label changes). It explains well under 1% of the variance.
"""

import regex

READS = ()

LATER_TOKENS = -0.03
SECOND_TOKEN = -0.125


def kind(text):
    s = text.strip()
    if not s:
        return "newline" if "\n" in text else "space"
    if regex.fullmatch(r"\p{Han}+", s):
        return "han"
    if regex.fullmatch(r"\p{L}+", s):
        return "word"
    if regex.fullmatch(r"\p{N}+", s):
        return "digit"
    if regex.fullmatch(r"[\p{P}\p{S}]+", s):
        return "punct"
    return "mixed"


OFFSET = {"space": 0.044, "newline": 0.022, "han": -0.014, "word": -0.005,
          "digit": 0.013, "punct": 0.013, "mixed": 0.034}


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if carry is None or docs[-1] != docs[-2]:
        k = 0
    else:
        k = carry + 1
    if k == 0:
        level = 0.0
    elif k == 1:
        level = SECOND_TOKEN
    else:
        level = LATER_TOKENS
    if k == 0:
        return k, level
    return k, level + OFFSET[kind(prefix.token_strings[-1])]

"""Coordination neuron: MLP hidden unit 5836 of layer 15 (its down_proj component).

Plain-terms summary. The unit is a sign-mixed signal with a clear pattern around
coordinated lists: it is high on the first word of the second item of a coordination,
and it is negative on the connective word ("or", "and") itself when that connective
opens an alternative after a comma.

  * after "and" / "or" (and their foreign equivalents), the next word starts a second
    conjunct. If that word is a noun, adjective or determiner, the unit is high:
    "Medical Directors and [Chief]", "a red lips and [hair]", "one or [two]".
  * after a list comma, the next word is mildly high: "apples, [pears]".
  * the connective itself, when it follows a comma ("..., [or] anywhere else"), is
    negative; other connectives are slightly negative.
  * everything else is near zero.

This explains only about 5% of the variance (eval: variance explained 0.049, r 0.22).
Its values are large and varied in every context. A lookup on the current and previous
token reaches only about 6%, and repetition of earlier text adds nothing. The rest of its
variance depends on context this program does not model. The program captures the
coordination pattern and nothing else.
"""

import wordnet

READS = ()

CONJUNCTIONS = {"and", "or", "nor", "und", "oder", "et", "ou", "y", "или", "и", "&", "和", "、"}
COMMAS = {",", "，", "、"}
NEGATIVE_CONNECTIVES = {"and", "or", "nor", "but"}
DETERMINERS = {
    "a", "an", "the", "some", "all", "no", "my", "her", "his", "its", "our", "their",
    "your", "one", "two", "three", "many", "most", "other", "each", "every", "both",
    "these", "those", "this", "that", "such", "any", "several", "few", "more", "non",
}


def is_noun_phrase_start(word):
    """True for a determiner, noun or adjective (by WordNet), False otherwise."""
    if word in DETERMINERS:
        return True
    try:
        return bool({"noun", "adjective"} & set(wordnet.parts_of_speech(word)))
    except Exception:
        return False


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if before in CONJUNCTIONS:
        value = 1.5 if is_noun_phrase_start(word) else 1.1
    elif before in COMMAS:
        value = 0.76
    else:
        value = 0.03
    if word in NEGATIVE_CONNECTIVES:
        value = -0.3 if before in COMMAS else -0.15
    return carry, float(value)

"""Layer 15 MLP hidden unit 5870 (component 5870 of down_proj), read as a
"producing a result" detector.

The component is almost exactly MLP hidden unit 5870 of layer 15, written into the
residual stream. It is a sparse spike detector: it is switched on by words that set
up producing, computing or obtaining something, and most of the time it is near 0.
This program predicts its activation from the current token and a little context:

- verbs of computing or generating a result ("generate", "calculate", "predict",
  "determine", "create", "obtain", "estimate", "extract", "derive", with -s/-d/-ed/-ing
  forms) fire strongly, about 3;
- "compute", "construct", "produce", "retrieve", "find", "identify", "returns",
  "define", "build" fire moderately, about 1.8;
- "get" fires moderately in prose (1.0) and strongly in code (2.4), where it names
  a function ("getName", "def get_...");
- in code, Java/C# member modifiers ("public", "static", "private") that open a
  method declaration fire strongly (4); in prose they are weak (0.9);
- the determiner right after such a verb ("calculate [the] speed") fires about 1.6;
- "new" and "into" fire weakly (1.1).

Everything else predicts 0. The activation's large negative values, and the
diffuse variation on common words like "the", "of", "to" and digits, are not modelled.
"""

READS = ()

STRONG = {"generate", "calculate", "predict", "determine", "create", "obtain", "estimate", "extract", "derive"}
MEDIUM = {"compute", "construct", "produce", "retrieve", "find", "identify", "returns", "define", "build"}
MODIFIERS = {"public", "static", "private", "protected"}
DETERMINERS = {"the", "a", "an"}
CODE_MARKS = set("{};()=<>")


def _forms(word):
    """A verb with its -s, -d, -ed and -ing forms."""
    return {word + s for s in ("", "s", "d", "ed", "ing")}


STRONG_ALL = set().union(*(_forms(w) for w in STRONG))
MEDIUM_ALL = set().union(*(_forms(w) for w in MEDIUM)) | _forms("get")
VERBS = STRONG_ALL | MEDIUM_ALL


def _word(s):
    return s.strip().lower()


def _in_code(prefix, n=20):
    """True when the last n tokens of this document contain code punctuation."""
    text = "".join(prefix.token_strings[-n:])
    return any(c in CODE_MARKS for c in text)


def step(carry, prefix, upstream):
    w = _word(prefix.token_strings[-1])
    code = _in_code(prefix)
    value = 0.0
    if w in STRONG_ALL:
        value = 3.0
    elif w in _forms("get"):
        value = 2.4 if code else 1.0
    elif w in MEDIUM_ALL:
        value = 1.8
    elif w in MODIFIERS:
        value = 4.0 if code else 0.9
    elif w in ("new", "into"):
        value = 1.1
    elif w in DETERMINERS:
        if any(_word(s) in VERBS for s in prefix.token_strings[-4:-1]):
            value = 1.6
    return carry, value

"""Layer 15, component 5872 of the MLP down projection, as a rule over the newest word.

This component is almost entirely one MLP hidden unit (unit 5872 of layer 15), and its
activation is diffuse: it depends on the surrounding text, and word identity explains only
a few percent of it. This program is a rough word-class guess, scored per token:

- Highest (about 0.8-0.9): absence and quantity words that open a noun phrase: without,
  sans, ohne, без, no, any, some, this, these; and the degree adverbs almost and often.
- High (about 0.6-0.8): verbs that tie an event to what follows or accompanies it:
  follow, accompany, result, lead, subsequent, preceded, offset.
- Middle (about 0.35): a, an, not, such, more, and, which, it, that, into.
- Auxiliaries (be, been, was, were, has, have, had, is, are) are about 0.3, but about 0 when
  they come straight after a personal pronoun (he was, I am, they are).
- Everything else, including 'the', prepositions and punctuation, sits near the average (0.09).

The values are the mean activation of each class over 4096 training rows, rounded.
"""

READS = ()

STRONG = {
    "without", "sans", "ohne", "без", "no", "any", "some", "this", "these", "almost", "often",
}
LINK_WORDS = {
    "follow", "followed", "follows", "following", "accompany", "accompanied", "accompanies",
    "result", "resulted", "results", "lead", "led", "leads", "subsequent", "subsequently",
    "preceded", "offset",
}
MIDDLE = {"a", "an", "not", "such", "more", "and", "which", "it", "that", "into"}
AUX_WORDS = {"be", "been", "was", "were", "has", "have", "had", "is", "are"}
PERSONAL_PRONOUNS = {"he", "she", "i", "we", "they", "you", "who"}

STRONG_VALUE, LINK_VALUE, MIDDLE_VALUE, AUX_VALUE, AUX_AFTER_PRONOUN, OTHER = (
    0.9, 0.8, 0.35, 0.3, 0.02, 0.09,
)


def step(carry, prefix, upstream):
    """The activation at the newest token, from that token and the one before it."""
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in STRONG:
        value = STRONG_VALUE
    elif word in LINK_WORDS:
        value = LINK_VALUE
    elif word in MIDDLE:
        value = MIDDLE_VALUE
    elif word in AUX_WORDS:
        value = AUX_AFTER_PRONOUN if before in PERSONAL_PRONOUNS else AUX_VALUE
    else:
        value = OTHER
    return carry, value

"""Layer 15 MLP output component 5873, as a readable rule set.

Mostly a diffuse, small contributor. Its large values sit on a few formulaic spots
where the model is inside a memorised phrase:

- the connective word of a relation name in a knowledge-base triple:
  "country [of] citizenship", "place [of] birth", "position played [on] team /",
  "languages spoken[,] written", "original language [of] film [or] TV show";
- the header line of a method that overrides a parent's (after an @Override
  annotation): its words are positive, and the '{' that opens its body is negative;
- a few repeated phrases: "Review the changes [and] make sure", "did not [produce]",
  "DESCRIPTION [OF]".

Everywhere else it predicts the component's typical value, slightly below zero.
"""

READS = ()

BASELINE = -0.06  # the component's typical value away from these spots

RELATION_HEADS = ("country", "place", "original language", "language", "manner", "field")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    before = "".join(prefix.token_strings[-6:-1]).rstrip()
    lines = ["", ""] + "".join(prefix.token_strings[-40:]).split("\n")
    if "\n" in cur:  # the token ends its line, e.g. " {\n"
        line, above = lines[-2], lines[-3]
    else:
        line, above = lines[-1], lines[-2]
    value = BASELINE
    if cur == " of" and before.endswith(RELATION_HEADS):
        value = 3.0
    elif cur == " on" and before.endswith("played"):
        value = 5.0
    elif cur in (" /", "/") and before.endswith("on team"):
        value = 6.0
    elif cur == "," and before.endswith("languages spoken"):
        value = 4.5
    elif cur == " or" and before.endswith(("film", "work")):
        value = 5.0
    elif cur == " and" and before.endswith("Review the changes"):
        value = 4.0
    elif cur == " produce" and before.endswith("did not"):
        value = 4.0
    elif cur == " OF" and before.endswith("DESCRIPTION"):
        value = 4.0
    elif "@Override" in above and "@Override" not in line:
        if "{" in cur:
            value = -2.5  # the '{' that opens an overriding method's body
        elif "\n" not in cur:
            value = 1.5  # the words of an overriding method's header line
    return carry, value

"""Layer-15 MLP down-projection component 5881: a "by" detector (agent or means),
with weaker responses to the words of Java-style import lines and to "by" in
French, Spanish and German.

In plain terms, the program writes:
- a strong value on the word "by" when it introduces an agent or a means after a
  verb or noun: "made by", "authored by", "captured by", "done by typing ...";
- nothing on "by" in arithmetic or fixed phrases: "divided by", "multiplied by",
  "divisible by", "followed by", "step by step";
- a weak value on the word tokens of an import, #include or package line, such
  as "import com.example.util" (punctuation and newlines get nothing);
- a weak value on "par", "por" and "durch", the agent words of other languages;
- 0 everywhere else.

The numbers are the component's mean activation in each group, measured on
training text. The component is diffuse: these groups explain about a tenth of
its variance, and most of the rest is spread thinly over common tokens.
"""
import re

READS = ()

BY_WORDS = {"by"}
NOT_AGENT_BEFORE = {"followed", "divided", "divisible", "multiplied", "multiply",
                    "divide", "step", "by"}
OTHER_AGENT_WORDS = {"par", "por", "durch"}
IMPORT_LINE = re.compile(r"(import|#include|package)\b")
WORD = re.compile(r"[A-Za-z]")
BY_VALUE = 3.0
OTHER_AGENT_VALUE = 1.2
IMPORT_VALUE = 0.7


def _line_so_far(prefix):
    """Text of the current line up to and including the newest token, same document only."""
    toks = prefix.token_strings
    docs = prefix.document_ids
    start = len(toks) - 1
    while start > 0 and docs[start - 1] == docs[-1] and "\n" not in toks[start - 1]:
        start -= 1
    return "".join(toks[start:])


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    word = cur.strip().lower()
    if "\n" in cur:
        return carry, 0.0
    if word in BY_WORDS:
        before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
        return carry, 0.0 if before in NOT_AGENT_BEFORE else BY_VALUE
    if word in OTHER_AGENT_WORDS:
        return carry, OTHER_AGENT_VALUE
    if IMPORT_LINE.match(_line_so_far(prefix).lstrip()) and WORD.search(cur):
        return carry, IMPORT_VALUE
    return carry, 0.0
